      </div>
      <div class="content">
        <h6>
          <b>Bemor:</b>
        </h6>
        <h6>{{ data?.patient?.name }} {{ data?.patient?.surename }}</h6>
      </div>
      <hr />
      <div class="queues" v-for="item in data?.queues || []" :key="item">
        <div class="content">
          <h6>
            <b>{{ item.service?.name }}:</b>
          </h6>
          <h6>{{ item.doctor?.user?.name }}</h6>
        </div>
        <div class="content">
          <h6>
            <b>{{ item.number }}-navbat:</b>
          </h6>
          <h6>{{ item.room }}-xona</h6>
        </div>
        <div class="content" v-if="item.hasConsultation">
          <h6>
            <i>Konsultatsiya</i>
          </h6>
          <h6>{{ _.format(item.consultationPrice) }}</h6>
        </div>
        <div
          class="content"
          v-for="procedure in item.queue_procedures || []"
          :key="procedure"
        >
          <h6>
            <i>{{ procedure.service_procedure.name }}</i>
          </h6>
          <h6>{{ _.format(procedure.price) }}</h6>
        </div>
        <h6 style="text-align: end">
          <b>
            {{
              _.format(
                item.queue_procedures?.reduce(
                  (acc, item) => acc + item.price,
                  0
                )
              )
            }}
          </b>
        </h6>
        <hr />
      </div>
      <div class="content">
        <h6>
          <b>Jami summa:</b>
        </h6>
        <h6>{{ _.format(data?.total_price) }} so'm</h6>
      </div>
      <div class="content" v-if="data?.discount > 0">
        <h6>
          <b>Chegirma summa:</b>
        </h6>
        <h6>{{ _.format(data?.discount) }} so'm</h6>
      </div>
      <div class="content">
        <h6>
          <b>To'lov summa:</b>
        </h6>
        <h6>{{ _.format(data?.total_price - data?.discount) }} so'm</h6>
      </div>
      <div class="content">
        <h6>
          <b>Sana:</b>
        </h6>
        <h6>
          {{ formattedDate }}
        </h6>
      </div>
    </div>
  </div>
</template>

<script>
import { catchError, inspection_get } from "../Utils/api";
export default {
  name: "mijoz-check",
  data() {
    return {
      _: Intl.NumberFormat(),
      data: {},
    };
  },
  computed: {
    formattedDate() {
      if (this.data?.date) {
        const day = new Date(this.data?.date)
          .getDate()
          .toString()
          .padStart(2, "0");
        const month = (new Date(this.data?.date).getMonth() + 1)
          .toString()
          .padStart(2, "0");
        const year = new Date(this.data?.date).getFullYear().toString();

        return `${day}-${month}-${year}`;
      }
    },
  },
  methods: {
    start(id) {
      inspection_get(id)
        .then((e) => {
          let total_price = null;
          e.data?.queues.forEach((element) => {
            total_price += element.consultationPrice;
            element.queue_procedures.forEach((procedure) => {
              total_price += procedure.price;
            });
          });
          e.data.total_price = total_price;
          this.data = e.data;
          this.create();
        })
        .catch((error) => {
          catchError(error);
        });
    },
    create() {
      let check = document.getElementById("ambulator-check");
      let winPrint = window.open();
      winPrint.document.head.innerHTML += `
            <style>
                * {
                    margin: 0;
                    font-family: sans-serif;
                    box-sizing: border-box;
                }
                h6 {
                    margin: 0 0 2px 0;
                    font-weight: 500;
                    line-height: 1.2;
                    color: inherit;
                    font-size: 8px;
                }
                #ambulator-check {
                    padding: 5px 5px;
                }
                .check-img {
                    display: flex;
                    justify-content: center;
                    margin-bottom: 10px;
                }
                body {
                    zoom: 100%;
                }
                .content, .inspections {
                    display: flex;
                    justify-content: space-between;
                }
                .content h6:last-child {
                    text-align: right;
                }
                hr {
                    border-top: 0.1px dashed #000;
                    border-bottom: none !important;
                    border-right: none !important;
                    border-left: none !important;
                    margin-bottom: 5px;
                }
            </style>`;
      winPrint.document.body.append(check);
      setTimeout(() => {
        winPrint.print();
        winPrint.close();
        document.getElementById("check-1").append(check);
      }, 500);
    },
  },
};
</script>
